import os
from typing import Any, Dict, List, Optional

from pydantic import BaseModel, Field, ValidationError, field_validator
from openai import OpenAI


class ConfidenceScore(BaseModel):
    field_name: str
    confidence: float = Field(ge=0.0, le=1.0)

    @field_validator("field_name")
    @classmethod
    def field_name_must_not_be_empty(cls, v: str) -> str:
        if not v.strip():
            raise ValueError("field_name must not be empty")
        return v


class ExtractedDocument(BaseModel):
    document_type: str
    vendor_name: str
    invoice_number: str
    invoice_date: str
    total_amount: float
    currency: str
    confidence_scores: List[ConfidenceScore]

    @field_validator("document_type", "vendor_name", "invoice_number", "invoice_date", "currency")
    @classmethod
    def required_strings_must_not_be_empty(cls, v: str) -> str:
        if not isinstance(v, str) or not v.strip():
            raise ValueError("required string field is missing or empty")
        return v

    @field_validator("confidence_scores")
    @classmethod
    def validate_confidence_coverage(cls, scores: List[ConfidenceScore]) -> List[ConfidenceScore]:
        required_fields = {
            "document_type",
            "vendor_name",
            "invoice_number",
            "invoice_date",
            "total_amount",
            "currency",
        }
        present = {s.field_name for s in scores}
        missing = required_fields - present
        if missing:
            raise ValueError(f"missing confidence scores for fields: {sorted(missing)}")
        return scores


def extract_and_validate_structured_document(document_text: str) -> Dict[str, Any]:
    if not document_text or not document_text.strip():
        raise ValueError("document_text must not be empty")

    api_key = os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise EnvironmentError("OPENAI_API_KEY is not set")

    client = OpenAI(api_key=api_key)

    response = client.responses.create(
        model="gpt-4.1-mini",
        input=[
            {
                "role": "system",
                "content": (
                    "You extract structured data from documents. "
                    "Return only valid JSON with the exact schema requested. "
                    "Provide confidence scores between 0 and 1 for each required field."
                ),
            },
            {
                "role": "user",
                "content": (
                    "Extract the following fields from this document:\n"
                    "- document_type\n"
                    "- vendor_name\n"
                    "- invoice_number\n"
                    "- invoice_date\n"
                    "- total_amount\n"
                    "- currency\n"
                    "- confidence_scores: array of objects with field_name and confidence\n\n"
                    f"Document:\n{document_text}"
                ),
            },
        ],
        text={
            "format": {
                "type": "json_schema",
                "name": "extracted_document",
                "schema": {
                    "type": "object",
                    "additionalProperties": False,
                    "properties": {
                        "document_type": {"type": "string"},
                        "vendor_name": {"type": "string"},
                        "invoice_number": {"type": "string"},
                        "invoice_date": {"type": "string"},
                        "total_amount": {"type": "number"},
                        "currency": {"type": "string"},
                        "confidence_scores": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "additionalProperties": False,
                                "properties": {
                                    "field_name": {"type": "string"},
                                    "confidence": {"type": "number", "minimum": 0, "maximum": 1},
                                },
                                "required": ["field_name", "confidence"],
                            },
                        },
                    },
                    "required": [
                        "document_type",
                        "vendor_name",
                        "invoice_number",
                        "invoice_date",
                        "total_amount",
                        "currency",
                        "confidence_scores",
                    ],
                },
            }
        },
    )

    raw_json = response.output_text

    try:
        validated = ExtractedDocument.model_validate_json(raw_json)
    except ValidationError as e:
        raise ValueError(f"Structured extraction validation failed: {e}") from e

    return validated.model_dump()
